from pathlib import Path
import json,re

root=Path('docs/design/mobile-pdf-annotation-editor-v1');root.mkdir(exist_ok=True)
assert not (root/'index.html').exists(), 'Frozen design source must not be overwritten'
base=Path('docs/design/mobile-pdf-navigation-v2/index.html').read_text(encoding='utf-8').split('</style>')[0]
css='''
/* annotation-editor */
.pdf-annotation-editor{--annotation-error:#a13e32;position:absolute;z-index:18;inset:0;display:flex;flex-direction:column;min-height:0;overflow:hidden;background:var(--bg);color:var(--ink)}
.annotation-editor-surface{display:flex;flex:1;flex-direction:column;min-height:0}
.annotation-editor-header{display:flex;align-items:center;gap:8px;flex:none;min-height:64px;padding:7.5px 8px;border-bottom:1px solid var(--line)}.annotation-editor-header h1{flex:1;min-width:0;margin:0;letter-spacing:normal;font-size:1.25rem;line-height:1.5;font-weight:700;overflow-wrap:anywhere}
.annotation-editor-back,.annotation-editor-close{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;padding:0;border:0;background:transparent;color:var(--muted)}
.annotation-editor-context{display:flex;gap:12px;align-items:start;flex:none;padding:12px 16px;border-bottom:1px solid var(--line)}.annotation-editor-context p{flex:1;min-width:0;margin:0;font-size:.8125rem;line-height:1.5384615385;color:var(--muted);overflow-wrap:anywhere}.annotation-editor-context span{flex:none;font-size:.8125rem;line-height:1.5384615385;color:var(--muted)}
.annotation-editor-body{flex:1;min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}
.annotation-editor-row{display:flex;align-items:center;gap:12px;width:100%;min-height:64px;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink);text-align:left;font:inherit}.annotation-editor-row>span{flex:1;min-width:0}.annotation-editor-row strong{display:block;font-size:1rem;line-height:1.5;font-weight:650}.annotation-editor-row small{display:block;margin-top:4px;font-size:.875rem;line-height:1.5;color:var(--muted);overflow-wrap:anywhere}.annotation-editor-row>svg{flex:none;color:var(--muted)}.annotation-source-row{margin-bottom:12px}.annotation-color-row{margin-bottom:20px}.annotation-color-value{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:.875rem;line-height:1.5}
.annotation-editor-swatch{display:inline-block;flex:none;width:16px;height:16px;border:1px solid #263a3033;border-radius:4px}.color-yellow{background:#ffe16a}.color-green{background:#88bc7c}.color-pink{background:#ed9cb5}.color-blue{background:#88b9ed}
.annotation-comment-label{display:flex;gap:8px;align-items:baseline;font-size:1rem;line-height:1.5;margin:0 0 8px}.annotation-comment-label small{color:var(--muted);font-size:.875rem}.annotation-comment-field{display:block;width:100%;min-width:0;min-height:168px;padding:12px;resize:vertical;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink);font:inherit;font-size:1rem;line-height:1.75}.annotation-comment-field:focus-visible{outline:2px solid var(--primary);outline-offset:2px}
.annotation-editor-error{font-size:.875rem;line-height:1.6;margin:16px 0 0;color:var(--annotation-error);overflow-wrap:anywhere}
.annotation-editor-footer,.annotation-editor-dialog-footer{display:flex;gap:8px;flex:none;padding:12px 16px;border-top:1px solid var(--line);background:var(--bg);max-height:45dvh;overflow:auto}.annotation-editor-footer{padding-bottom:calc(12px + env(safe-area-inset-bottom))}.annotation-editor-footer .button,.annotation-editor-dialog-footer .button{flex:1;min-width:0;min-height:48px;padding:11px 10px;border-radius:10px;font-size:.875rem;line-height:1.7142857143;font-weight:400}
.annotation-editor-layer{position:absolute;z-index:20;inset:0;display:grid;place-items:center;padding:16px;background:#14261d66}.annotation-editor-dialog{display:flex;flex-direction:column;width:min(100%,400px);max-height:100%;min-height:0;border:1px solid var(--line);border-radius:16px;background:var(--bg);overflow:hidden;box-shadow:0 12px 40px #14261d26}
.annotation-editor-dialog-header{display:flex;gap:8px;align-items:center;flex:none;min-height:64px;padding:7.5px 8px 7.5px 16px;border-bottom:1px solid var(--line);background:var(--bg)}.annotation-editor-dialog-header h2{flex:1;min-width:0;margin:0;letter-spacing:normal;font-size:1.25rem;line-height:1.5;font-weight:700;overflow-wrap:anywhere}.annotation-editor-dialog-body{min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}.annotation-editor-choice{display:flex;align-items:center;gap:12px;width:100%;min-height:56px;padding:12px 4px;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);font:inherit;font-size:1rem;line-height:1.5;text-align:left}.annotation-editor-choice:last-child{border:0}.annotation-editor-choice>span{flex:1}.annotation-editor-choice svg{color:var(--primary);flex:none}
.annotation-editor-quote{margin:0;padding:0 0 0 12px;border-left:3px solid var(--primary-soft);white-space:pre-wrap;overflow-wrap:anywhere;font-size:1rem;line-height:1.75}.annotation-discard-copy{margin:0;font-size:.875rem;line-height:1.6;overflow-wrap:anywhere}.annotation-editor-dialog-footer .danger-button{background:var(--annotation-error);border-color:var(--annotation-error);color:var(--bg)}
@media(max-width:340px){.annotation-editor-context{flex-wrap:wrap;gap:4px 12px}.annotation-editor-context p{flex-basis:100%}.annotation-editor-row{flex-wrap:wrap}.annotation-editor-row>span{flex-basis:calc(100% - 36px)}.annotation-editor-footer,.annotation-editor-dialog-footer{flex-direction:column}.annotation-editor-footer .button,.annotation-editor-dialog-footer .button{flex:none}.annotation-editor-dialog-header h2{font-size:1.125rem}}
@media(max-height:400px){.annotation-editor-header{min-height:49px;padding:0 8px}.annotation-editor-header h1{font-size:1rem}.annotation-editor-context{display:none}.annotation-editor-body{padding:12px}.annotation-editor-layer{padding:8px}.annotation-editor-dialog-header{min-height:49px;padding:0 8px 0 12px}.annotation-editor-dialog-header h2{font-size:1rem}.annotation-editor-dialog-body{padding:12px}.annotation-editor-footer,.annotation-editor-dialog-footer{flex-direction:row;padding:8px 12px}.annotation-editor-footer .button,.annotation-editor-dialog-footer .button{flex:1;padding:8px 6px;font-size:.75rem;line-height:1.5}}
/* end annotation-editor */
'''
icons={}
for key,file in {'back':'arrow-left','help':'circle-question-mark','close':'x','chevron':'chevron-right','check':'circle-check'}.items():
 source=Path('node_modules/lucide-vue-next/dist/esm/icons/'+file+'.js').read_text(encoding='utf-8')
 nodes=re.findall(r'\[\s*"(path|circle|line|polyline|rect)"\s*,\s*\{\s*([^}]+)\s*\}\s*\]',source,re.S)
 assert len(nodes)==len(re.findall(r'\[\s*"(?:path|circle|line|polyline|rect)"',source)),file
 icons[key]=''.join('<'+tag+' '+' '.join(k+'="'+v+'"' for k,v in re.findall(r'(\w+):\s*"([^"]*)"',fields) if k!='key')+' />' for tag,fields in nodes)
script=r'''
const screen=new URLSearchParams(location.search).get('screen')||'edit',icons=ICONS,icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const comment=screen==='new-comment'||screen==='invalid'?'':screen==='edit'?'为重要的想法留出空间。':screen==='new-highlight'?'':'带着想法回来😀',highlight=!['new-comment','invalid'].includes(screen),isNew=['new-comment','invalid','new-highlight'].includes(screen),panel=['color','quote','discard'].includes(screen)?screen:'';
const rows=`${highlight?`<button class="annotation-editor-row annotation-source-row"><span><strong>原文摘录</strong><small>Make room for ideas</small></span>${icon('chevron',20)}</button>`:''}<button class="annotation-editor-row annotation-color-row"><span><strong>标记颜色</strong></span><div class="annotation-color-value"><i class="annotation-editor-swatch color-yellow"></i>黄色</div>${icon('chevron',20)}</button>`;
document.querySelector('.phone').innerHTML=`<section class="pdf-annotation-editor"><div class="annotation-editor-surface"><header class="annotation-editor-header"><button class="annotation-editor-back">${icon('back')}</button><h1>${isNew?'记录想法':'编辑批注'}</h1><button class="mobile-help-trigger">${icon('help',20)}</button></header><div class="annotation-editor-context"><p>阅读导航.pdf</p><span>第 1 页 · ${highlight?'高亮':'评论'}</span></div><div class="annotation-editor-body">${rows}<label class="annotation-comment-label" for="pdf-comment">我的想法${highlight?'<small>可留空</small>':''}</label><textarea id="pdf-comment" class="annotation-comment-field" rows="5">${comment}</textarea>${screen==='invalid'?'<p class="annotation-editor-error">请写下想法后保存。</p>':''}</div><footer class="annotation-editor-footer"><button class="button">放弃输入</button><button class="button primary-button">保存批注</button></footer></div>${panel?`<div class="annotation-editor-layer"><section class="annotation-editor-dialog"><header class="annotation-editor-dialog-header"><h2>${panel==='color'?'标记颜色':panel==='quote'?'原文摘录':'放弃输入？'}</h2><button class="annotation-editor-close">${icon('close')}</button></header><div class="annotation-editor-dialog-body">${panel==='color'?Object.entries({yellow:'黄色',green:'绿色',pink:'粉色',blue:'蓝色'}).map(([c,t])=>`<button class="annotation-editor-choice" aria-pressed="${c==='yellow'}"><i class="annotation-editor-swatch color-${c}"></i><span>${t}</span>${c==='yellow'?icon('check',22):''}</button>`).join(''):panel==='quote'?'<blockquote class="annotation-editor-quote">Make room for ideas</blockquote>':'<p class="annotation-discard-copy">尚未保存的修改会丢弃，已保存批注不变。</p>'}</div><footer class="annotation-editor-dialog-footer"><button class="button">${panel==='discard'?'继续编辑':'返回编辑'}</button>${panel==='discard'?'<button class="button danger-button">确认放弃</button>':''}</footer></section></div>`:''}</section>`;
if(!panel)document.querySelector('textarea').focus();
'''.replace('ICONS',json.dumps(icons,ensure_ascii=False))
(root/'index.html').write_text(base+css+'</style><div class="phone"></div><script>'+script+'</script></html>',encoding='utf-8')
capture=Path('scripts/capture-mobile-pdf-bookmark-task-design.mjs').read_text(encoding='utf-8').replace('pdf-bookmark-task','pdf-annotation-editor').replace("['empty','list','menu','rename','pending','delete','undo','invalid']","['new-comment','new-highlight','edit','color','quote','discard','invalid']").replace('annotation-editor-v3','annotation-editor-v1').replace('design-freeze-v3','design-freeze-v1').replace('design-v3-','design-v1-').replace("'7cb25e276'","'821c71606'")
old="['.pdf-navigation','.pdf-navigation-heading','.pdf-navigation-context','.pdf-navigation-tabs','.pdf-navigation-body','.pdf-bookmark-add','.pdf-bookmark-card','.pdf-bookmark-layer','.pdf-bookmark-dialog','.pdf-bookmark-dialog-header','.pdf-bookmark-dialog-body','.pdf-bookmark-dialog-footer','#pdf-bookmark-name','.pdf-navigation-footer']"
new="['.pdf-annotation-editor','.annotation-editor-header','.annotation-editor-context','.annotation-editor-body','.annotation-source-row','.annotation-color-row','#pdf-comment','.annotation-editor-footer','.annotation-editor-layer','.annotation-editor-dialog','.annotation-editor-dialog-header','.annotation-editor-dialog-body','.annotation-editor-dialog-footer']"
assert old in capture;capture=capture.replace(old,new)
Path('scripts/capture-mobile-pdf-annotation-editor-design.mjs').write_text(capture,encoding='utf-8')
